import {
  designReferenceKeys,
  type AgentReferenceSearchResult,
  type DesignLibraryMatch,
  type DesignLibraryReference,
  type DesignLibrarySource,
  type DesignReferenceSearchResult,
} from '../../types/design-library';
import { hasCompletedAnalysis } from '../../types/design-profile';

export const AGENT_SEARCH_DEFAULT_LIMIT = 8;
export const AGENT_SEARCH_MAX_LIMIT = 12;
export const AGENT_SEARCH_DESCRIPTION_CHARACTERS = 1_000;
export const AGENT_SEARCH_RESULT_BYTES = 16 * 1024;

export const budgetAgentSearchResult = (result: AgentReferenceSearchResult) => {
  const shape = (hits: AgentReferenceSearchResult['results']) => {
    const sources = new Map<string, DesignLibrarySource>();
    for (const hit of hits)
      for (const source of hit.sources) sources.set(source.id, source);
    return {
      profileId: result.profileId,
      query: result.query,
      status: result.status,
      autonomy: result.autonomy,
      searchMode: result.searchMode,
      coverage: result.coverage,
      sources: [...sources.values()],
      results: hits.map((hit) => ({
        id: hit.id,
        key: hit.key,
        title: hit.title,
        provider: hit.provider,
        ...(hit.url ? { url: hit.url } : {}),
        description:
          hit.description === null
            ? null
            : [...hit.description]
                .slice(0, AGENT_SEARCH_DESCRIPTION_CHARACTERS)
                .join(''),
        hasAnalysis: hit.hasAnalysis,
        matchedBy: hit.matchedBy,
        imageCount: hit.imageCount,
        sourceIds: hit.sources.map((source) => source.id),
        isIncluded: hit.isIncluded,
      })),
      truncated:
        hits.length < Math.min(result.results.length, AGENT_SEARCH_MAX_LIMIT),
    };
  };
  let hits = result.results.slice(0, AGENT_SEARCH_MAX_LIMIT);
  let shaped = shape(hits);
  while (
    hits.length &&
    Buffer.byteLength(JSON.stringify(shaped)) > AGENT_SEARCH_RESULT_BYTES
  ) {
    hits = hits.slice(0, -1);
    shaped = shape(hits);
  }
  return shaped;
};

export const profileSearchResult = ({
  profileId,
  query,
  matches,
  allReferences,
  sources,
  coverage,
  limit = 24,
}: {
  profileId: string;
  query: string;
  matches: DesignLibraryMatch[];
  allReferences: DesignLibraryReference[];
  sources: DesignLibrarySource[];
  coverage: {
    references: number;
    analyzed: number;
    provisional: number;
    indexed: number;
  };
  limit?: number;
}): DesignReferenceSearchResult => {
  const keys = designReferenceKeys(allReferences);
  const sourceById = new Map(sources.map((source) => [source.id, source]));
  return {
    profileId,
    query,
    coverage: {
      saved: coverage.references,
      analyzed: coverage.analyzed,
      provisional: coverage.provisional,
      indexed: coverage.indexed,
    },
    results: matches.slice(0, limit).flatMap((reference) => {
      const key = keys.get(reference.id);
      if (!key) return [];
      const memberships = reference.sourceIds.flatMap((id) => {
        const source = sourceById.get(id);
        return source ? [source] : [];
      });
      return [
        {
          id: reference.id,
          key,
          title: reference.title,
          provider: reference.provider,
          ...(reference.url ? { url: reference.url } : {}),
          description: reference.observation?.description ?? null,
          hasAnalysis: hasCompletedAnalysis(reference.observation),
          matchedBy: reference.matchedBy,
          imageCount: reference.media.length,
          sources: memberships,
          isIncluded: memberships.some((source) => source.isIncluded),
        },
      ];
    }),
  };
};
